#include <algorithm>

const FIT_UINT16 Profile::GetFieldIndex(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
{
    const MESG *mesg = GetMesg(mesgNum);

    if (mesg == NULL)
        return FIT_UINT16_INVALID;

    // Binary search since fields are sorted by num (per SDK design)
    const FIELD *begin = mesg->fields;
    const FIELD *end = begin + mesg->numFields;

    auto it = std::lower_bound(begin, end, fieldNum,
        [](const FIELD& a, FIT_UINT8 b) { return a.num < b; });

    return (it != end && it->num == fieldNum) 
        ? static_cast<FIT_UINT16>(it - begin) 
        : FIT_UINT16_INVALID;
}
